def subtract(a, b):
    # Merge intervals in a list
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Disjoint, add new interval
                merged.append([start, end])

        return merged

    # Merge both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []
    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        current = [[a_start, a_end]]

        # Subtract each interval in b_merged
        for b_start, b_end in b_merged:
            next_current = []

            for c_start, c_end in current:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    next_current.append([c_start, c_end])
                else:
                    # There is overlap, keep the parts outside b
                    if c_start < b_start:
                        next_current.append([c_start, b_start])
                    if c_end > b_end:
                        next_current.append([b_end, c_end])

            current = next_current

        result.extend(current)

    return result

